/**
 * @fileoverview Utility functions for grouping individual logs into trips.
 * This is based on the assumption that a significant time gap between
 * the end of one log and the start of the next indicates a new trip.
 */

// A trip is considered separate if there is more than 1 hour between logs.
export const TRIP_GAP_THRESHOLD_SECONDS = 3600; // 1 hour

/**
 * Groups a flat list of log index entries into distinct trips.
 *
 * @param {Array<Object>} logs - A list of log index objects from the API.
 * Each object must have 'timestamp' and 'duration_sec' properties.
 * @returns {Array<Object>} A list of trip group objects, where each object
 * contains the logs belonging to that trip.
 */
export function groupLogsIntoTrips(logs) {
  if (!logs || logs.length === 0) {
    return [];
  }

  // Ensure logs are processed in chronological order.
  const sortedLogs = [...logs].sort((a, b) => a.timestamp - b.timestamp);
  const tripGroups = [];
  if (sortedLogs.length > 0) {
    // Initialize the first trip with the first log.
    let currentTrip = {
      groupId: `trip-${sortedLogs[0].timestamp}`,
      logs: [sortedLogs[0]],
      startTime: sortedLogs[0].timestamp,
      endTime: sortedLogs[0].timestamp + sortedLogs[0].duration_sec
    };
    tripGroups.push(currentTrip);
    for (let i = 1; i < sortedLogs.length; i++) {
      const log = sortedLogs[i];
      const prevLog = sortedLogs[i - 1];
      const prevLogEndTime = prevLog.timestamp + prevLog.duration_sec;
      const timeGap = log.timestamp - prevLogEndTime;
      if (timeGap > TRIP_GAP_THRESHOLD_SECONDS) {
        // Time gap is large enough, start a new trip.
        currentTrip = {
          groupId: `trip-${log.timestamp}`,
          logs: [log],
          startTime: log.timestamp,
          endTime: log.timestamp + log.duration_sec
        };
        tripGroups.push(currentTrip);
      } else {
        // Time gap is small, add the log to the current trip.
        currentTrip.logs.push(log);
        currentTrip.endTime = Math.max(currentTrip.endTime, log.timestamp + log.duration_sec);
      }
    }
  }

  // Generate a more stable groupId from the IDs of the logs in the trip.
  // This prevents the ID from changing if the start time is adjusted.
  tripGroups.forEach(group => {
    const ids = group.logs.map(l => l.id).join('-');
    group.groupId = `trip-${ids}`;
  });
  return tripGroups;
}

